UnityEditor.EditorApplication.delayCall+=()=>{try{
UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/DansBackyardReverse.unity");var branch=UnityEngine.Object.FindObjectsByType<Racer.WoodlandRoute>().First(b=>b.title.StartsWith("Storm"));float start=branch.Project(new Vector3(104.3f,0,3),out _),lip=branch.Project(new Vector3(95.8f,0,-24),out _);var mf=GameObject.Find("Ground_Gully straight launch").GetComponent<MeshFilter>();var mesh=UnityEngine.Object.Instantiate(mf.sharedMesh);var v=mesh.vertices;
for(int i=0;i<branch.points.Length;i++){float s=branch.Project(branch.points[i],out _);if(s>=start&&s<=lip){float u=(s-start)/(lip-start);branch.points[i].y=36.95f-1.2f*u+4.55f*u*u;}}
for(int i=0;i<v.Length;i++){float s=branch.Project(v[i],out _);if(i%4==1||i%4==2)v[i].y=branch.At(s,out _).y;}mesh.vertices=v;mesh.RecalculateNormals();mesh.RecalculateBounds();UnityEditor.AssetDatabase.CreateAsset(mesh,"Assets/Track/ReverseShortcuts/Measured gully jump.asset");mf.sharedMesh=mesh;mf.GetComponent<MeshCollider>().sharedMesh=mesh;UnityEditor.EditorUtility.SetDirty(branch);UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(mf.gameObject.scene);UnityEditor.SceneManagement.EditorSceneManager.SaveScene(mf.gameObject.scene);UnityEditor.AssetDatabase.SaveAssets();System.IO.File.WriteAllText("Docs/ReverseShortcuts/jump-profile.txt","Measured touchdown correction: ramp lip 40.30m, approximately 0.28 rise/run; original takeoff area and landing corridor retained. No existing ramp modified.");
}catch(Exception e){System.IO.File.WriteAllText("Docs/ReverseShortcuts/jump-profile-error.txt",e.ToString());}};return "Correct measured motorcycle overshoot with local launch grade";
